struct Dhikr { const char* title; const char* body; };
static const Dhikr MORNING[11] = {
  { "Ayat al-Kursi",
    "Recite Ayat al-Kursi, verse 255 of Al-Baqarah, once. Allah, there is no god but He, the Ever Living, the Sustainer of all. Neither drowsiness nor sleep overtakes Him. Whoever recites it in the morning is under protection until the evening." },
  { "The Three Quls",
    "Recite Al-Ikhlas, Al-Falaq and An-Nas three times each. Say: He is Allah, One. Say: I seek refuge with the Lord of the daybreak. Say: I seek refuge with the Lord of mankind. They suffice against all harm." },
  { "Morning words",
    "Asbahna wa asbahal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la sharika lah. We have entered the morning and the whole kingdom belongs to Allah. Praise is for Allah. There is no god but Allah alone, with no partner." },
  { "Istighfar",
    "Allahumma anta rabbi la ilaha illa anta, khalaqtani wa ana abduka, wa ana ala ahdika wa wadika mastatatu. O Allah, You are my Lord. There is no god but You. You created me and I am Your servant. I keep Your covenant as best I can. I seek refuge in You from the evil I have done. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for none forgives sins but You." },
  { "Contentment",
    "Raditu billahi rabban, wa bil islami dinan, wa bi Muhammadin nabiyyan. I am content with Allah as my Lord, with Islam as my religion, and with Muhammad as my Prophet. Say it three times." },
  { "O Ever Living",
    "Ya Hayyu ya Qayyum, bi rahmatika astaghith, aslih li shani kullahu wa la takilni ila nafsi tarfata ayn. O Ever Living, O Sustainer of all, by Your mercy I seek help. Set right all my affairs and do not leave me to myself even for the blink of an eye." },
  { "Against harm",
    "Bismillahil ladhi la yadurru maa ismihi shayun fil ardi wa la fis samai wa huwas Samiul Alim. In the name of Allah, with whose name nothing on earth or in the heaven can cause harm, and He is the All Hearing, the All Knowing. Say it three times." },
  { "Glory to Allah",
    "Subhanallahi wa bihamdih. Glory is to Allah and praise is His. Said one hundred times in a day, it is said that no one will come with better than it, except one who said the same or more." },
  { "Wellbeing",
    "Allahumma inni asalukal afwa wal afiyah fid dunya wal akhirah. O Allah, I ask You for pardon and wellbeing in this world and the next. Ask for it in your religion, your worldly life, your family and your wealth." },
  { "Good of the day",
    "Allahumma inni asaluka khayra hadhal yawm, fathahu wa nasrahu wa nurahu wa barakatahu wa hudah. O Allah, I ask You for the good of this day, its opening, its help, its light, its blessing and its guidance." },
  { "Countless glory",
    "Subhanallahi wa bihamdihi adada khalqih, wa rida nafsih, wa zinata arshih, wa midada kalimatih. Glory and praise be to Allah as many times as the number of His creation, as befits His pleasure, as the weight of His throne and as the ink of His words. Say it three times." },
};
#define MORNING_N 11

